import java.util.Scanner;

public class CabFare {
    private String carType;
    private double km;
    private double total;

    public CabFare(String car, double k) {
        carType = car.toUpperCase();
        km = k;
        total = 0.0;
    }

    public void compute() {
        double rate, minFare;
        switch (carType) {
            case "HATCHBACK":
                rate = 12.0;
                minFare = 150.0;
                break;
            case "SEDAN":
                rate = 16.0;
                minFare = 200.0;
                break;
            case "SUV":
                rate = 22.0;
                minFare = 300.0;
                break;
            default:
                rate = 15.0;
                minFare = 180.0;
        }

        double fare = Math.max(minFare, km * rate);
        total = fare + (0.05 * fare); // 5% allowance
    }

    public void printBill() {
        System.out.println("\n============== CITYCAB RECEIPT ==============");
        System.out.println("Vehicle Category : " + carType);
        System.out.println("Distance Covered : " + km + " km");
        System.out.println("Total Fare (tax) : Rs. " + total);
        System.out.println("==============================================");
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Car Type (HATCHBACK / SEDAN / SUV): ");
        String car = in.nextLine();
        System.out.print("Enter Distance in km: ");
        double distance = in.nextDouble();

        CabFare ride = new CabFare(car, distance);
        ride.compute();
        ride.printBill();
    }
}
```

