import java.util.Scanner;

public class MergeSortedArrays {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] A = new int[5];
        int[] B = new int[5];
        int[] C = new int[10];

        System.out.println("Enter 5 sorted integers for Array A:");
        for (int i = 0; i < 5; i++) A[i] = sc.nextInt();

        System.out.println("Enter 5 sorted integers for Array B:");
        for (int i = 0; i < 5; i++) B[i] = sc.nextInt();

        int i = 0, j = 0, k = 0;
        while (i < 5 && j < 5) {
            if (A[i] <= B[j]) {
                C[k++] = A[i++];
            } else {
                C[k++] = B[j++];
            }
        }

        while (i < 5) C[k++] = A[i++];
        while (j < 5) C[k++] = B[j++];

        System.out.print("\nMerged Sorted Array C: ");
        for (int val : C) System.out.print(val + " ");
        System.out.println();
    }
}
```

