import java.util.Scanner;
import java.util.Arrays;

public class AnagramCheck {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter first word: ");
        String w1 = in.next().toUpperCase();
        System.out.print("Enter second word: ");
        String w2 = in.next().toUpperCase();

        if (w1.length() != w2.length()) {
            System.out.println(w1 + " and " + w2 + " are NOT Anagrams (different lengths).");
            return;
        }

        char[] a1 = w1.toCharArray();
        char[] a2 = w2.toCharArray();

        // Sort character arrays using simple bubble sort
        sortChars(a1);
        sortChars(a2);

        if (Arrays.equals(a1, a2)) {
            System.out.println(w1 + " and " + w2 + " are ANAGRAMS.");
        } else {
            System.out.println(w1 + " and " + w2 + " are NOT Anagrams.");
        }
    }

    private static void sortChars(char[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = 0; j < arr.length - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    char temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
    }
}
```

