import java.util.Scanner;

public class FascinatingNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a number (>= 100): ");
        int num = sc.nextInt();

        if (num < 100) {
            System.out.println("Please enter a number with at least 3 digits.");
            return;
        }

        int p2 = num * 2;
        int p3 = num * 3;
        String concat = "" + num + p2 + p3;

        boolean isFascinating = true;
        if (concat.length() != 9) {
            isFascinating = false;
        } else {
            for (char digit = '1'; digit <= '9'; digit++) {
                int count = 0;
                for (int i = 0; i < concat.length(); i++) {
                    if (concat.charAt(i) == digit) count++;
                }
                if (count != 1) {
                    isFascinating = false;
                    break;
                }
            }
        }

        System.out.println("\nConcatenated String: " + concat);
        if (isFascinating) {
            System.out.println(num + " is a FASCINATING NUMBER.");
        } else {
            System.out.println(num + " is NOT a Fascinating Number.");
        }
    }
}
```

