import java.util.Scanner;

public class ClockwiseBoundaryTraversal {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter square matrix order N (3 to 6): ");
        int n = in.nextInt();

        int[][] mat = new int[n][n];
        System.out.println("Enter " + (n * n) + " elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = in.nextInt();
            }
        }

        System.out.print("\nClockwise Boundary Elements: ");

        // Top row
        for (int j = 0; j < n; j++) System.out.print(mat[0][j] + " ");

        // Right column
        for (int i = 1; i < n; i++) System.out.print(mat[i][n - 1] + " ");

        // Bottom row
        for (int j = n - 2; j >= 0; j--) System.out.print(mat[n - 1][j] + " ");

        // Left column
        for (int i = n - 2; i > 0; i--) System.out.print(mat[i][0] + " ");

        System.out.println();
    }
}
```

