public class OverloadSearch {
    public int search(int[] arr, int key) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == key) return i;
        }
        return -1;
    }

    public int search(String[] names, String target) {
        for (int i = 0; i < names.length; i++) {
            if (names[i].equalsIgnoreCase(target)) return i;
        }
        return -1;
    }

    public static void main(String[] args) {
        OverloadSearch os = new OverloadSearch();

        int[] nums = {12, 45, 67, 89, 90};
        int numIdx = os.search(nums, 67);
        System.out.println("Search 67 in integer array: Index " + numIdx);

        String[] cities = {"Delhi", "Mumbai", "Kolkata", "Chennai"};
        int cityIdx = os.search(cities, "Kolkata");
        System.out.println("Search 'Kolkata' in string array: Index " + cityIdx);
    }
}
```

